const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

class DocumentStore {
  constructor(config) {
    this.baseDir = config.baseDir || '/var/documents';
    this.maxFileSize = config.maxFileSize || 10485760;
    this.allowedExtensions = config.allowedExtensions || ['.txt', '.pdf', '.doc'];
    this.auditLog = [];
  }

  getConfig() {
    return {
      baseDir: this.baseDir,
      maxFileSize: this.maxFileSize,
      allowedExtensions: [...this.allowedExtensions]
    };
  }

  updateConfig(updates) {
    const safeKeys = ['maxFileSize', 'allowedExtensions'];
    for (const key of safeKeys) {
      if (updates[key] !== undefined) {
        this[key] = updates[key];
      }
    }
  }

  logAccess(action, filePath, user) {
    this.auditLog.push({
      timestamp: Date.now(),
      action,
      filePath,
      user: String(user).substring(0, 64)
    });
  }
}

class RequestContext {
  constructor(defaults) {
    this.user = 'anonymous';
    this.permissions = ['read'];
    this.baseDir = defaults.baseDir;
    this.requestId = crypto.randomBytes(8).toString('hex');
  }

  applySession(sessionData) {
    if (sessionData && typeof sessionData === 'object') {
      if (sessionData.user && typeof sessionData.user === 'string') {
        this.user = sessionData.user.substring(0, 64);
      }
      if (Array.isArray(sessionData.permissions)) {
        this.permissions = sessionData.permissions.filter(p => typeof p === 'string');
      }
    }
  }
}

function createContext(store, requestBody) {
  const defaults = store.getConfig();
  const ctx = new RequestContext(defaults);

  if (requestBody.session) {
    ctx.applySession(requestBody.session);
  }

  // Apply request-level overrides for pagination/filtering
  if (requestBody.options && typeof requestBody.options === 'object') {
    Object.assign(ctx, requestBody.options);
  }

  return ctx;
}

function validateFilename(filename) {
  if (typeof filename !== 'string') return false;
  if (filename.length === 0 || filename.length > 255) return false;
  if (filename.includes('\0')) return false;
  // Block directory traversal sequences
  if (filename.includes('..')) return false;
  if (filename.includes('/') || filename.includes('\\')) return false;
  // Only allow alphanumeric, dash, underscore, dot
  if (!/^[a-zA-Z0-9_\-]+(\.[a-zA-Z0-9]+)?$/.test(filename)) return false;
  return true;
}

function resolveFilePath(ctx, filename) {
  const resolved = path.resolve(ctx.baseDir, filename);
  const normalizedBase = path.resolve(ctx.baseDir);

  // Ensure resolved path is within the base directory
  if (!resolved.startsWith(normalizedBase + path.sep) && resolved !== normalizedBase) {
    return null;
  }
  return resolved;
}

function handleRead(store, ctx, params) {
  if (!ctx.permissions.includes('read')) {
    return { status: 403, body: { error: 'Permission denied' } };
  }

  const filename = params.filename;
  if (!validateFilename(filename)) {
    return { status: 400, body: { error: 'Invalid filename' } };
  }

  const ext = path.extname(filename).toLowerCase();
  const config = store.getConfig();
  if (!config.allowedExtensions.includes(ext)) {
    return { status: 400, body: { error: 'File type not allowed' } };
  }

  const filePath = resolveFilePath(ctx, filename);
  if (!filePath) {
    return { status: 403, body: { error: 'Access denied' } };
  }

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    store.logAccess('read', filePath, ctx.user);
    return { status: 200, body: { content, requestId: ctx.requestId } };
  } catch (e) {
    return { status: 404, body: { error: 'File not found' } };
  }
}

function handleList(store, ctx) {
  if (!ctx.permissions.includes('read')) {
    return { status: 403, body: { error: 'Permission denied' } };
  }

  const dirPath = path.resolve(ctx.baseDir);
  try {
    const files = fs.readdirSync(dirPath);
    return { status: 200, body: { files, requestId: ctx.requestId } };
  } catch (e) {
    return { status: 500, body: { error: 'Unable to list directory' } };
  }
}

const store = new DocumentStore({ baseDir: '/var/documents' });

const server = http.createServer((req, res) => {
  if (req.method !== 'POST') {
    res.writeHead(405);
    res.end(JSON.stringify({ error: 'Method not allowed' }));
    return;
  }

  let body = '';
  req.on('data', chunk => {
    if (body.length > 65536) return;
    body += chunk;
  });

  req.on('end', () => {
    let parsed;
    try {
      parsed = JSON.parse(body);
    } catch (e) {
      res.writeHead(400);
      res.end(JSON.stringify({ error: 'Invalid JSON' }));
      return;
    }

    const ctx = createContext(store, parsed);
    let result;

    switch (parsed.action) {
      case 'read':
        result = handleRead(store, ctx, parsed.params || {});
        break;
      case 'list':
        result = handleList(store, ctx);
        break;
      case 'config':
        store.updateConfig(parsed.params || {});
        result = { status: 200, body: { config: store.getConfig() } };
        break;
      default:
        result = { status: 400, body: { error: 'Unknown action' } };
    }

    res.writeHead(result.status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(result.body));
  });
});

server.listen(8080, '127.0.0.1');
